function g(o,t){let n=0;for(let l=0;l<t.length;l++){const f=t[l];f===255?(n++,l++):n+=o[f]}return n}function h(o,t,n){const l=new Uint32Array(t.length);for(let e=1;e<t.length;e++)l[e]=l[e-1]+t[e-1];const f=new Uint8Array(g(t,n));let i=0;for(let e=0;e<n.length;e++){const d=n[e];if(d===255)e++,f[i++]=n[e];else{let r=t[d],c=l[d];for(;r-- >0;)f[i++]=o[c++]}}return f}export{h as decodeFsst};
